/**
 * Gate A milestone A2: the node-predicate projection ships enabled for outgoing nodes, and a store that cannot fit the
 * projection comes up healthy without it.
 * <p>
 * The two directions are deliberately separate tests rather than one parameterised one, because they fail for different
 * reasons and a reviewer reading a failure needs to know which of the two switches is broken. The build-time switch is
 * resolved once from an explicit properties function, never from the live process, so these tests do not depend on
 * system-property ordering across the class.
 */
class LmdbNodePredicateSwitchTest {

	private TripleStore tripleStore;
	private LmdbDirectAdjacencyStore store;

	private static long uri(long payload) {
		return ValueIds.createId(ValueIds.T_URI, payload);
	}

	private static final long S1 = uri(1);
	private static final long S2 = uri(2);
	private static final long P1 = uri(100);
	private static final long P2 = uri(101);
	private static final long O1 = uri(11);

	@AfterEach
	void tearDown() throws Exception {
		System.clearProperty(LmdbDirectAdjacencyStore.NODE_PREDICATE_SERVE_PROPERTY);
		if (store != null) {
			store.close();
		}
		if (tripleStore != null) {
			tripleStore.close();
		}
	}

	private void open(File dataDir, Boolean construction, Boolean serving) throws Exception {
		tripleStore = new TripleStore(dataDir, new LmdbStoreConfig("spoc,posc"), null);
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		UnaryOperator<String> properties = name -> construction != null
				&& LmdbDirectAdjacencyOptions.NODE_PREDICATE_PROJECTION_PROPERTY.equals(name)
						? String.valueOf(construction)
						: null;
		LmdbDirectAdjacencyOptions options = LmdbDirectAdjacencyOptions.resolve(config, 8L << 30, properties, 4);
		if (serving == null) {
			System.clearProperty(LmdbDirectAdjacencyStore.NODE_PREDICATE_SERVE_PROPERTY);
		} else {
			System.setProperty(LmdbDirectAdjacencyStore.NODE_PREDICATE_SERVE_PROPERTY, String.valueOf(serving));
		}
		store = new LmdbDirectAdjacencyStore(tripleStore, null, new AtomicBoolean(false), options);
		tripleStore.setDirectAdjacencyCommitHooks(store.commitListener(), store.newCommitDelta());

		tripleStore.startTransaction();
		tripleStore.storeTriple(S1, P1, O1, 0, true);
		tripleStore.storeTriple(S1, P2, O1, 0, true);
		tripleStore.storeTriple(S2, P1, O1, 0, true);
		tripleStore.commit();
		store.applyCommitted(tripleStore.drainDirectAdjacencyCommitDelta());
		assertThat(store.buildNowForTest()).isTrue();
	}

	private List<long[]> rowsFor(long subject) throws IOException {
		try (LmdbAdjacencyReadView view = store.acquire(tripleStore.getDataRevision())) {
			RecordIterator it = store.tryOpen(view, null, subject, -1, -1, -1, true);
			if (it == null) {
				return null;
			}
			List<long[]> rows = new ArrayList<>();
			try {
				long[] quad;
				while ((quad = it.next()) != null) {
					rows.add(new long[] { quad[TripleIndex.SUBJ_IDX], quad[TripleIndex.PRED_IDX],
							quad[TripleIndex.OBJ_IDX] });
				}
			} finally {
				it.close();
			}
			return rows;
		}
	}

	/**
	 * The shipped default builds and serves the outgoing projection. Incoming remains a separate opt-in because its
	 * object domain includes referenced literals and costs materially more memory.
	 */
	@Test
	void constructionAndServingDefaultOn(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		LmdbDirectAdjacencyOptions defaults = LmdbDirectAdjacencyOptions.resolve(config, 8L << 30, name -> null, 4);
		assertThat(defaults.nodePredicateProjectionEnabled()).isTrue();
		assertThat(defaults.nodePredicateProjectionIncomingEnabled()).isFalse();

		open(dataDir, null, null);

		LmdbAdjacencyMemoryAccount account = store.memoryAccount();
		assertThat(account.chargedBytes(MemoryKind.NODE_PREDICATE_NATIVE)).isPositive();
		assertThat(account.chargedBytes(MemoryKind.NODE_PREDICATE_JAVA)).isPositive();

		LmdbInMemoryAdjacencyIndex base = store.publishedStateForTest().base();
		assertThat(base.nodePredicateIndexOrNull()).isNotNull();
		assertThat(base.supportsPredicateEnumeration(LmdbAdjacencyPlane.PLANE_OUTGOING_EXPLICIT)).isTrue();
		assertThat(store.nodePredicateServingEnabled()).isTrue();

		long before = store.snapshotMetrics().fallbacks(FallbackReason.PREDICATE_ENUMERATION_INCOMPLETE);
		assertThat(rowsFor(S1)).as("the default projection serves bound-node predicate enumeration").hasSize(2);
		assertThat(store.snapshotMetrics().fallbacks(FallbackReason.PREDICATE_ENUMERATION_INCOMPLETE))
				.isEqualTo(before);
	}

	/**
	 * The per-call gate stops the projection specialization immediately, without removing the universal traversal.
	 */
	@Test
	void servingSwitchStopsOnlyTheProjectionWithoutARebuild(@TempDir File dataDir) throws Exception {
		open(dataDir, true, true);
		assertThat(store.publishedStateForTest().base().nodePredicateIndexOrNull()).isNotNull();
		assertThat(rowsFor(S1)).hasSize(2);

		System.setProperty(LmdbDirectAdjacencyStore.NODE_PREDICATE_SERVE_PROPERTY, "false");
		long before = store.snapshotMetrics().fallbacks(FallbackReason.PREDICATE_ENUMERATION_INCOMPLETE);
		assertThat(rowsFor(S1)).as("the general traversal replaces the disabled specialization").hasSize(2);
		assertThat(store.snapshotMetrics().fallbacks(FallbackReason.PREDICATE_ENUMERATION_INCOMPLETE))
				.isEqualTo(before);

		// ...and back on again, still without a rebuild: the structure was never destroyed, only bypassed.
		System.setProperty(LmdbDirectAdjacencyStore.NODE_PREDICATE_SERVE_PROPERTY, "true");
		assertThat(rowsFor(S1)).hasSize(2);
	}

	/**
	 * With construction on, the projection is charged under its own kinds so the per-kind breakdown in both lifecycle
	 * log lines and the metrics snapshot can show what it costs (milestone A3).
	 */
	@Test
	void constructionOnChargesTheProjectionUnderItsOwnKinds(@TempDir File dataDir) throws Exception {
		open(dataDir, true, true);
		LmdbAdjacencyMemoryAccount account = store.memoryAccount();
		assertThat(account.chargedBytes(MemoryKind.NODE_PREDICATE_NATIVE)).isPositive();
		assertThat(account.chargedBytes(MemoryKind.NODE_PREDICATE_JAVA)).isPositive();

		LmdbAdjacencyMetrics.Snapshot snapshot = store.snapshotMetrics();
		assertThat(snapshot.nodePredicateNativeBytes)
				.isEqualTo(account.chargedBytes(MemoryKind.NODE_PREDICATE_NATIVE));
		assertThat(snapshot.nodePredicateJavaBytes).isEqualTo(account.chargedBytes(MemoryKind.NODE_PREDICATE_JAVA));
		// The projection's bytes are its own, not folded into the primary index's.
		assertThat(account.memoryUsageSummary()).contains("NODE_PREDICATE_NATIVE").contains("NODE_PREDICATE_JAVA");
	}

	/** Incoming is a separate decision and is not implied by the outgoing switch. */
	@Test
	void incomingIsGatedSeparatelyAndImpliesOutgoing() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		LmdbDirectAdjacencyOptions outgoingOnly = LmdbDirectAdjacencyOptions.resolve(config, 8L << 30,
				name -> LmdbDirectAdjacencyOptions.NODE_PREDICATE_PROJECTION_PROPERTY.equals(name) ? "true" : null, 4);
		assertThat(outgoingOnly.nodePredicateProjectionEnabled()).isTrue();
		assertThat(outgoingOnly.nodePredicateProjectionIncomingEnabled()).isFalse();

		LmdbDirectAdjacencyOptions both = LmdbDirectAdjacencyOptions.resolve(config, 8L << 30,
				name -> LmdbDirectAdjacencyOptions.NODE_PREDICATE_PROJECTION_PROPERTY.equals(name)
						|| LmdbDirectAdjacencyOptions.NODE_PREDICATE_PROJECTION_INCOMING_PROPERTY.equals(name) ? "true"
								: null,
				4);
		assertThat(both.nodePredicateProjectionEnabled()).isTrue();
		assertThat(both.nodePredicateProjectionIncomingEnabled()).isTrue();

		// Incoming alone is not a configuration the structure can hold, so it resolves to "no projection at all"
		// rather than to a half-built one.
		LmdbDirectAdjacencyOptions incomingWithoutOutgoing = LmdbDirectAdjacencyOptions.resolve(config, 8L << 30,
				name -> LmdbDirectAdjacencyOptions.NODE_PREDICATE_PROJECTION_PROPERTY.equals(name) ? "false"
						: LmdbDirectAdjacencyOptions.NODE_PREDICATE_PROJECTION_INCOMING_PROPERTY.equals(name) ? "true"
								: null,
				4);
		assertThat(incomingWithoutOutgoing.nodePredicateProjectionEnabled()).isFalse();
		assertThat(incomingWithoutOutgoing.nodePredicateProjectionIncomingEnabled()).isFalse();
	}

	/**
	 * A typo in a boolean switch must be reported rather than silently read as "off", which is what
	 * {@code Boolean.parseBoolean} would do and which would make a configured-on store quietly behave like a
	 * configured-off one.
	 */
	@Test
	void amalformedSwitchValueIsRejected() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		assertThatThrownBy(() -> LmdbDirectAdjacencyOptions.resolve(config, 8L << 30,
				name -> LmdbDirectAdjacencyOptions.NODE_PREDICATE_PROJECTION_PROPERTY.equals(name) ? "yes" : null, 4))
						.isInstanceOf(IllegalArgumentException.class)
						.hasMessageContaining(LmdbDirectAdjacencyOptions.NODE_PREDICATE_PROJECTION_PROPERTY);
	}
}
